      "head": "<meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n  <meta name=\"theme-color\" content=\"#071c1b\">\n  <title>Ómnibus en Búzios: urbanos y desde Río | Ernestinho Carioca</title>\n  <meta name=\"description\" content=\"Cómo usar los autobuses para llegar y desplazarte sin depender del auto.\" data-ec-content=\"Cómo usar los autobuses para llegar y desplazarte sin depender del auto.\">\n  <meta property=\"og:type\" content=\"website\" data-ec-content=\"website\">\n  <meta property=\"og:title\" content=\"Ómnibus en Búzios: urbanos y desde Río | Ernestinho Carioca\">\n  <meta property=\"og:description\" content=\"Cómo usar los autobuses para llegar y desplazarte sin depender del auto.\">\n  <meta property=\"og:url\" content=\"https://www.ernestinhocarioca.com.br/destinos/buzios/transportes/onibus/\">\n  <meta property=\"og:site_name\" content=\"Ernestinho Carioca\" data-ec-content=\"Ernestinho Carioca\">\n  <meta property=\"og:image\" content=\"https://www.ernestinhocarioca.com.br/assets/brand/ec-mark.png\" data-ec-content=\"https://www.ernestinhocarioca.com.br/assets/brand/ec-mark.png\">\n  <meta property=\"og:image:alt\" content=\"Paisaje costero de Búzios\" data-ec-content=\"Paisaje costero de Búzios\">\n  <meta name=\"twitter:card\" content=\"summary_large_image\" data-ec-content=\"summary_large_image\">\n  <meta name=\"twitter:title\" content=\"Ómnibus en Búzios: urbanos y desde Río | Ernestinho Carioca\">\n  <meta name=\"twitter:description\" content=\"Cómo usar los autobuses para llegar y desplazarte sin depender del auto.\">\n  <meta name=\"twitter:image\" content=\"https://www.ernestinhocarioca.com.br/assets/brand/ec-mark.png\" data-ec-content=\"https://www.ernestinhocarioca.com.br/assets/brand/ec-mark.png\">\n  <link rel=\"canonical\" href=\"https://www.ernestinhocarioca.com.br/destinos/buzios/transportes/onibus/\">\n  <link rel=\"icon\" type=\"image/png\" sizes=\"192x192\" href=\"/assets/brand/ec-mark.png\">\n  <link rel=\"apple-touch-icon\" href=\"/assets/brand/ec-mark.png\">\n  <script type=\"application/ld+json\">{\"@context\":\"https://schema.org\",\"@type\":\"WebPage\",\"name\":\"Ómnibus en Búzios: urbanos y desde Río | Ernestinho Carioca\",\"description\":\"Cómo usar los autobuses para llegar y desplazarte sin depender del auto.\",\"url\":\"https://www.ernestinhocarioca.com.br/destinos/buzios/transportes/onibus/\",\"inLanguage\":\"es\",\"isPartOf\":{\"@type\":\"WebSite\",\"name\":\"Ernestinho Carioca\",\"url\":\"https://www.ernestinhocarioca.com.br/\"}}</script>\n<meta property=\"og:locale\" content=\"es_ES\"><link rel=\"alternate\" hreflang=\"es\" href=\"https://www.ernestinhocarioca.com.br/destinos/buzios/transportes/onibus/\"><link rel=\"alternate\" hreflang=\"pt-BR\" href=\"https://www.ernestinhocarioca.com.br/pt/destinos/buzios/transportes/onibus/\"><link rel=\"alternate\" hreflang=\"en\" href=\"https://www.ernestinhocarioca.com.br/en/destinos/buzios/transportes/onibus/\"><link rel=\"alternate\" hreflang=\"x-default\" href=\"https://www.ernestinhocarioca.com.br/destinos/buzios/transportes/onibus/\"><script type=\"application/ld+json\" data-ec-breadcrumb=\"\">{\"@context\":\"https://schema.org\",\"@type\":\"BreadcrumbList\",\"itemListElement\":[{\"@type\":\"ListItem\",\"position\":1,\"name\":\"Ernestinho Carioca\",\"item\":\"https://www.ernestinhocarioca.com.br/\"},{\"@type\":\"ListItem\",\"position\":2,\"name\":\"Ómnibus en Búzios: urbanos y desde Río\",\"item\":\"https://www.ernestinhocarioca.com.br/destinos/buzios/transportes/onibus/\"}]}</script>"
