      "head": "<meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n  <meta name=\"theme-color\" content=\"#071c1b\">\n  <title>Ônibus em Búzios: municipais e saindo do Rio | Ernestinho Carioca</title>\n  <meta name=\"description\" content=\"Como usar ônibus para chegar e circular sem depender de carro.\" data-ec-content=\"Como usar ônibus para chegar e circular sem depender de carro.\">\n  <meta property=\"og:type\" content=\"website\" data-ec-content=\"website\">\n  <meta property=\"og:title\" content=\"Ônibus em Búzios: municipais e saindo do Rio | Ernestinho Carioca\">\n  <meta property=\"og:description\" content=\"Como usar ônibus para chegar e circular sem depender de carro.\">\n  <meta property=\"og:url\" content=\"https://www.ernestinhocarioca.com.br/pt/destinos/buzios/transportes/onibus/\">\n  <meta property=\"og:site_name\" content=\"Ernestinho Carioca\" data-ec-content=\"Ernestinho Carioca\">\n  <meta property=\"og:image\" content=\"https://www.ernestinhocarioca.com.br/assets/brand/ec-mark.png\" data-ec-content=\"https://www.ernestinhocarioca.com.br/assets/brand/ec-mark.png\">\n  <meta property=\"og:image:alt\" content=\"Paisagem do litoral de Búzios\" data-ec-content=\"Paisagem do litoral de Búzios\">\n  <meta name=\"twitter:card\" content=\"summary_large_image\" data-ec-content=\"summary_large_image\">\n  <meta name=\"twitter:title\" content=\"Ônibus em Búzios: municipais e saindo do Rio | Ernestinho Carioca\">\n  <meta name=\"twitter:description\" content=\"Como usar ônibus para chegar e circular sem depender de carro.\">\n  <meta name=\"twitter:image\" content=\"https://www.ernestinhocarioca.com.br/assets/brand/ec-mark.png\" data-ec-content=\"https://www.ernestinhocarioca.com.br/assets/brand/ec-mark.png\">\n  <link rel=\"canonical\" href=\"https://www.ernestinhocarioca.com.br/pt/destinos/buzios/transportes/onibus/\">\n  <link rel=\"icon\" type=\"image/png\" sizes=\"192x192\" href=\"/assets/brand/ec-mark.png\">\n  <link rel=\"apple-touch-icon\" href=\"/assets/brand/ec-mark.png\">\n  <script type=\"application/ld+json\">{\"@context\":\"https://schema.org\",\"@type\":\"WebPage\",\"name\":\"Ônibus em Búzios: municipais e saindo do Rio | Ernestinho Carioca\",\"description\":\"Como usar ônibus para chegar e circular sem depender de carro.\",\"url\":\"https://www.ernestinhocarioca.com.br/pt/destinos/buzios/transportes/onibus/\",\"inLanguage\":\"pt-BR\",\"isPartOf\":{\"@type\":\"WebSite\",\"name\":\"Ernestinho Carioca\",\"url\":\"https://www.ernestinhocarioca.com.br/\"}}</script>\n<meta property=\"og:locale\" content=\"pt_BR\"><link rel=\"alternate\" hreflang=\"es\" href=\"https://www.ernestinhocarioca.com.br/destinos/buzios/transportes/onibus/\"><link rel=\"alternate\" hreflang=\"pt-BR\" href=\"https://www.ernestinhocarioca.com.br/pt/destinos/buzios/transportes/onibus/\"><link rel=\"alternate\" hreflang=\"en\" href=\"https://www.ernestinhocarioca.com.br/en/destinos/buzios/transportes/onibus/\"><link rel=\"alternate\" hreflang=\"x-default\" href=\"https://www.ernestinhocarioca.com.br/destinos/buzios/transportes/onibus/\"><script type=\"application/ld+json\" data-ec-breadcrumb=\"\">{\"@context\":\"https://schema.org\",\"@type\":\"BreadcrumbList\",\"itemListElement\":[{\"@type\":\"ListItem\",\"position\":1,\"name\":\"Ernestinho Carioca\",\"item\":\"https://www.ernestinhocarioca.com.br/pt/\"},{\"@type\":\"ListItem\",\"position\":2,\"name\":\"Ônibus em Búzios: municipais e saindo do Rio\",\"item\":\"https://www.ernestinhocarioca.com.br/pt/destinos/buzios/transportes/onibus/\"}]}</script>"
