      "head": "<meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n  <meta name=\"theme-color\" content=\"#071c1b\">\n  <title>Uber e 99 em Búzios | Ernestinho Carioca</title>\n  <meta name=\"description\" content=\"Quando os aplicativos ajudam e como planejar a volta.\" data-ec-content=\"Quando os aplicativos ajudam e como planejar a volta.\">\n  <meta property=\"og:type\" content=\"website\" data-ec-content=\"website\">\n  <meta property=\"og:title\" content=\"Uber e 99 em Búzios | Ernestinho Carioca\">\n  <meta property=\"og:description\" content=\"Quando os aplicativos ajudam e como planejar a volta.\">\n  <meta property=\"og:url\" content=\"https://www.ernestinhocarioca.com.br/pt/destinos/buzios/transportes/uber-99/\">\n  <meta property=\"og:site_name\" content=\"Ernestinho Carioca\" data-ec-content=\"Ernestinho Carioca\">\n  <meta property=\"og:image\" content=\"https://www.ernestinhocarioca.com.br/assets/brand/ec-mark.png\" data-ec-content=\"https://www.ernestinhocarioca.com.br/assets/brand/ec-mark.png\">\n  <meta property=\"og:image:alt\" content=\"Paisagem do litoral de Búzios\" data-ec-content=\"Paisagem do litoral de Búzios\">\n  <meta name=\"twitter:card\" content=\"summary_large_image\" data-ec-content=\"summary_large_image\">\n  <meta name=\"twitter:title\" content=\"Uber e 99 em Búzios | Ernestinho Carioca\">\n  <meta name=\"twitter:description\" content=\"Quando os aplicativos ajudam e como planejar a volta.\">\n  <meta name=\"twitter:image\" content=\"https://www.ernestinhocarioca.com.br/assets/brand/ec-mark.png\" data-ec-content=\"https://www.ernestinhocarioca.com.br/assets/brand/ec-mark.png\">\n  <link rel=\"canonical\" href=\"https://www.ernestinhocarioca.com.br/pt/destinos/buzios/transportes/uber-99/\">\n  <link rel=\"icon\" type=\"image/png\" sizes=\"192x192\" href=\"/assets/brand/ec-mark.png\">\n  <link rel=\"apple-touch-icon\" href=\"/assets/brand/ec-mark.png\">\n  <script type=\"application/ld+json\">{\"@context\":\"https://schema.org\",\"@type\":\"WebPage\",\"name\":\"Uber e 99 em Búzios | Ernestinho Carioca\",\"description\":\"Quando os aplicativos ajudam e como planejar a volta.\",\"url\":\"https://www.ernestinhocarioca.com.br/pt/destinos/buzios/transportes/uber-99/\",\"inLanguage\":\"pt-BR\",\"isPartOf\":{\"@type\":\"WebSite\",\"name\":\"Ernestinho Carioca\",\"url\":\"https://www.ernestinhocarioca.com.br/\"}}</script>\n<meta property=\"og:locale\" content=\"pt_BR\"><link rel=\"alternate\" hreflang=\"es\" href=\"https://www.ernestinhocarioca.com.br/destinos/buzios/transportes/uber-99/\"><link rel=\"alternate\" hreflang=\"pt-BR\" href=\"https://www.ernestinhocarioca.com.br/pt/destinos/buzios/transportes/uber-99/\"><link rel=\"alternate\" hreflang=\"en\" href=\"https://www.ernestinhocarioca.com.br/en/destinos/buzios/transportes/uber-99/\"><link rel=\"alternate\" hreflang=\"x-default\" href=\"https://www.ernestinhocarioca.com.br/destinos/buzios/transportes/uber-99/\"><script type=\"application/ld+json\" data-ec-breadcrumb=\"\">{\"@context\":\"https://schema.org\",\"@type\":\"BreadcrumbList\",\"itemListElement\":[{\"@type\":\"ListItem\",\"position\":1,\"name\":\"Ernestinho Carioca\",\"item\":\"https://www.ernestinhocarioca.com.br/pt/\"},{\"@type\":\"ListItem\",\"position\":2,\"name\":\"Uber e 99 em Búzios\",\"item\":\"https://www.ernestinhocarioca.com.br/pt/destinos/buzios/transportes/uber-99/\"}]}</script>"
